import java.util.*;

class Solution {
    public int[] maxSlidingWindow(int[] nums, int k) {
        int n = nums.length;
        int[] result = new int[n - k + 1];
        Deque<Integer> deque = new ArrayDeque<>();

        for (int right = 0; right < n; right++) {
            while (!deque.isEmpty() && deque.peekFirst() <= right - k) {
                deque.pollFirst();
            }
            while (!deque.isEmpty() && nums[deque.peekLast()] <= nums[right]) {
                deque.pollLast();
            }
            deque.offerLast(right);

            if (right >= k - 1) {
                result[right - k + 1] = nums[deque.peekFirst()];
            }
        }

        return result;
    }
}

import java.util.*;

class Solution {
    public int[] maxSlidingWindow(int[] nums, int k) {
        int n = nums.length;
        int[] result = new int[n - k + 1];
        PriorityQueue<int[]> heap = new PriorityQueue<>((a, b) -> {
            if (a[0] != b[0]) {
                return Integer.compare(b[0], a[0]);
            }
            return Integer.compare(b[1], a[1]);
        });

        for (int right = 0; right < n; right++) {
            heap.offer(new int[] {nums[right], right});

            while (heap.peek()[1] <= right - k) {
                heap.poll();
            }

            if (right >= k - 1) {
                result[right - k + 1] = heap.peek()[0];
            }
        }

        return result;
    }
}

class Solution {
    public int[] maxSlidingWindow(int[] nums, int k) {
        int n = nums.length;
        int[] leftMax = new int[n];
        int[] rightMax = new int[n];

        for (int i = 0; i < n; i++) {
            if (i % k == 0) {
                leftMax[i] = nums[i];
            } else {
                leftMax[i] = Math.max(leftMax[i - 1], nums[i]);
            }

            int j = n - 1 - i;
            if (j == n - 1 || (j + 1) % k == 0) {
                rightMax[j] = nums[j];
            } else {
                rightMax[j] = Math.max(rightMax[j + 1], nums[j]);
            }
        }

        int[] result = new int[n - k + 1];
        for (int start = 0; start <= n - k; start++) {
            int end = start + k - 1;
            result[start] = Math.max(rightMax[start], leftMax[end]);
        }
        return result;
    }
}

import java.util.*;

class Solution {
    public int[] maxSlidingWindow(int[] nums, int k) {
        int n = nums.length;
        int[] result = new int[n - k + 1];
        TreeMap<Integer, Integer> counts = new TreeMap<>();

        for (int right = 0; right < n; right++) {
            counts.merge(nums[right], 1, Integer::sum);

            if (right >= k) {
                removeOne(counts, nums[right - k]);
            }

            if (right >= k - 1) {
                result[right - k + 1] = counts.lastKey();
            }
        }

        return result;
    }

    private void removeOne(TreeMap<Integer, Integer> counts, int value) {
        int nextCount = counts.get(value) - 1;
        if (nextCount == 0) {
            counts.remove(value);
        } else {
            counts.put(value, nextCount);
        }
    }
}
